def get_unique_filepath(filepath):
    """
    If a file path exists, it will add a number to the end of the file name
    until it finds a unique file name.
    """
    if not os.path.exists(filepath):
        return filepath

    directory, filename = os.path.split(filepath)
    filename_sans_ext, ext = os.path.splitext(filename)

    counter = 1
    new_filepath = os.path.join(directory, f"{filename_sans_ext}_{counter}{ext}")

    while os.path.exists(new_filepath):
        counter += 1
        new_filepath = os.path.join(directory, f"{filename_sans_ext}_{counter}{ext}")

    return new_filepath

def main():
    if not os.path.exists(DUPLICATES_FILE):
        print(f"Error: Duplicates file not found at {DUPLICATES_FILE}")
        return

    if not os.path.exists(GRAVITY_WELL):
        print(f"Error: Gravity well directory not found at {GRAVITY_WELL}")
        return

    with open(DUPLICATES_FILE, 'r') as f:
        lines = f.readlines()

    groups = defaultdict(list)
    current_hash = None
    for line in lines:
        line = line.strip()
        if not line:
            current_hash = None
            continue

        parts = line.split(maxsplit=1)
        if len(parts) < 2:
            continue

        file_hash, file_path = parts
        if current_hash != file_hash:
            current_hash = file_hash

        # All paths in duplicates.txt are relative to Q_pixel8
        full_path = os.path.join('Q_pixel8', file_path)
        groups[current_hash].append(full_path)

    for file_hash, files in groups.items():
        if len(files) < 2:
            continue

        file_to_keep = choose_file_to_keep(files)
        print(f"Keeping: {file_to_keep}")

        for file_path in files:
            if file_path != file_to_keep:
                if os.path.exists(file_path):
                    try:
                        destination_path = get_unique_filepath(os.path.join(GRAVITY_WELL, os.path.basename(file_path)))
                        shutil.move(file_path, destination_path)
                        print(f"  Moved: {file_path} to {destination_path}")
                    except Exception as e:
                        print(f"  Error moving {file_path}: {e}")
                else:
                    print(f"  Skipped (not found): {file_path}")
        print("-" * 20)

